What is the output of this program?

#include <stdio.h>
int countVowels(char str[]) {
    int count = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        char c = str[i];
        if (c == 'a' || c == 'e' || c == 'i'
                || c == 'o' || c == 'u' || c == 'A'
                || c == 'E' || c == 'I' || c == 'O'
                || c == 'U') {
            count++;
        }
    }
    return count;
}
int main() {
    char text[] = "Procedural";
    int total = countVowels(text);
    printf("'%s' has %d vowels.\n", text, total);
    return 0;
}

What is the output of this program?

#include <stdio.h>
void fixA(char *ptr) {
    while (*ptr != '\0') {
        if (*ptr == 'a') *ptr = 'A';
        ptr++;
    }
}
void clearText(char *ptr) {
    while (*ptr != '\0') {
        *ptr = '-';
        ptr++;
    }
}
int main() {
    char text[] = "banana";
    int choice = 1;
    if (choice == 1) {
        fixA(text);
    } else if (choice == 2) {
        clearText(text);
    }
    printf("Result: %s\n", text);
    return 0;
}

